import { writeFile } from 'node:fs/promises'

const target = await fetch('http://127.0.0.1:9223/json/new?about:blank', { method: 'PUT' }).then((response) => response.json())
const socket = new WebSocket(target.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  socket.addEventListener('open', resolve, { once: true })
  socket.addEventListener('error', reject, { once: true })
})
let sequence = 0
const pending = new Map()
const eventWaiters = new Map()
const requests = []
const responses = []
const exceptions = []
const logEntries = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.id) {
    const handler = pending.get(message.id)
    if (!handler) return
    pending.delete(message.id)
    message.error ? handler.reject(new Error(JSON.stringify(message.error))) : handler.resolve(message.result)
    return
  }
  if (message.method === 'Network.requestWillBeSent') requests.push(message.params.request.url)
  if (message.method === 'Network.responseReceived') responses.push({ url: message.params.response.url, status: message.params.response.status })
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails)
  if (message.method === 'Log.entryAdded') logEntries.push(message.params.entry)
  const waiter = eventWaiters.get(message.method)
  if (waiter) {
    eventWaiters.delete(message.method)
    waiter(message.params)
  }
})
function send(method, params = {}) {
  const id = ++sequence
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject })
    socket.send(JSON.stringify({ id, method, params }))
  })
}
function waitForEvent(method) { return new Promise((resolve) => eventWaiters.set(method, resolve)) }
async function evaluate(expression) {
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails))
  return result.result.value
}
async function settle() {
  await evaluate('new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))')
  await new Promise((resolve) => setTimeout(resolve, 550))
}
async function navigate() {
  const loaded = waitForEvent('Page.loadEventFired')
  await send('Page.navigate', { url: 'http://127.0.0.1:5173/' })
  await loaded
  await settle()
}
async function key(keyValue, code, virtualKey, text) {
  const down = { key: keyValue, code, windowsVirtualKeyCode: virtualKey }
  if (text) {
    down.type = 'keyDown'
    down.text = text
    down.unmodifiedText = text
  } else down.type = 'rawKeyDown'
  await send('Input.dispatchKeyEvent', down)
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: keyValue, code, windowsVirtualKeyCode: virtualKey })
  await settle()
}
async function clickButton() {
  const rect = await evaluate("(() => { const r = document.querySelector('button').getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 }; })()")
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', ...rect, button: 'left', clickCount: 1 })
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...rect, button: 'left', clickCount: 1 })
  await settle()
}
async function screenshot(name) {
  const result = await send('Page.captureScreenshot', { format: 'png', fromSurface: true, captureBeyondViewport: false })
  await writeFile(`/Users/zeh/Documents/elsewhere/tasks/reports/assets/TASK-001/${name}.png`, Buffer.from(result.data, 'base64'))
}
await send('Page.enable')
await send('Runtime.enable')
await send('Network.enable')
await send('Log.enable')
const results = []
let keyboardEvidence
for (const [width, height] of [[390, 844], [1440, 900], [320, 844]]) {
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false })
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'no-preference' }] })
  await navigate()
  const home = await evaluate(`(() => {
    const button = document.querySelector('button')
    const rect = button.getBoundingClientRect()
    const root = document.documentElement
    return {
      viewport: { width: innerWidth, height: innerHeight },
      layoutViewportWidth: root.clientWidth,
      documentWidth: root.scrollWidth,
      documentHeight: root.scrollHeight,
      horizontalOverflow: root.scrollWidth > root.clientWidth,
      title: document.querySelector('h1').innerText,
      button: { text: button.innerText, x: rect.x, y: rect.y, width: rect.width, height: rect.height, withinHorizontalViewport: rect.left >= 0 && rect.right <= root.clientWidth },
      pageScrollable: root.scrollHeight > innerHeight
    }
  })()`)
  await screenshot(`home-${width}x${height}`)
  const record = { home }
  if (width !== 320) {
    await clickButton()
    record.intro = await evaluate(`(() => ({
      heading: document.querySelector('h1').innerText,
      activeElement: document.activeElement.innerText,
      disclaimerPresent: document.body.innerText.includes('这是一段虚构的平行人生，不代表对真实未来的预测。'),
      returnButton: document.querySelector('button').innerText
    }))()`)
    await screenshot(`intro-${width}x${height}`)
    await clickButton()
    record.mouseReturn = await evaluate("document.querySelector('h1').innerText")

    await navigate()
    const keyboard = {}
    await key('Tab', 'Tab', 9)
    keyboard.tabToStart = await evaluate("({ active: document.activeElement.innerText, focusVisible: document.activeElement.matches(':focus-visible'), outline: getComputedStyle(document.activeElement).outline })")
    await key('Enter', 'Enter', 13, '\r')
    keyboard.enterStart = await evaluate("({ heading: document.querySelector('h1').innerText, active: document.activeElement.innerText })")
    await key('Tab', 'Tab', 9)
    keyboard.tabToReturn = await evaluate("({ active: document.activeElement.innerText, focusVisible: document.activeElement.matches(':focus-visible'), outline: getComputedStyle(document.activeElement).outline })")
    if (width === 390) await screenshot('keyboard-focus-return')
    await key(' ', 'Space', 32, ' ')
    keyboard.spaceReturn = await evaluate("({ heading: document.querySelector('h1').innerText, active: document.activeElement.innerText })")
    await key(' ', 'Space', 32, ' ')
    keyboard.spaceRestart = await evaluate("({ heading: document.querySelector('h1').innerText, active: document.activeElement.innerText })")
    await key('Tab', 'Tab', 9)
    await key('Enter', 'Enter', 13, '\r')
    keyboard.enterReturn = await evaluate("({ heading: document.querySelector('h1').innerText, active: document.activeElement.innerText })")
    record.keyboard = keyboard
    if (width === 390) keyboardEvidence = keyboard
  }
  if (width === 390) {
    await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] })
    await navigate()
    record.reducedMotion = await evaluate(`(() => {
      const screen = getComputedStyle(document.querySelector('.screen-enter'))
      const orbit = getComputedStyle(document.querySelector('.orbit-outer'))
      const button = getComputedStyle(document.querySelector('button'))
      return { mediaMatches: matchMedia('(prefers-reduced-motion: reduce)').matches, screenAnimation: screen.animationName, orbitAnimation: orbit.animationName, buttonTransitionDuration: button.transitionDuration }
    })()`)
    await screenshot('home-390x844-reduced-motion')
  }
  results.push(record)
}
const network = [...new Set(requests)].map((url) => ({ url, status: responses.findLast((entry) => entry.url === url)?.status ?? null }))
const output = {
  results,
  network,
  externalRequests: network.filter(({ url }) => /^https?:/.test(url) && !url.startsWith('http://127.0.0.1:5173/')),
  failedResponses: responses.filter(({ status }) => status >= 400),
  exceptions,
  logEntries: logEntries.filter((entry) => entry.level === 'error' || entry.level === 'warning')
}
await writeFile('/Users/zeh/Documents/elsewhere/tasks/reports/assets/TASK-001/browser-results.json', JSON.stringify(output, null, 2) + '\n')
await writeFile('/Users/zeh/Documents/elsewhere/tasks/reports/assets/TASK-001/keyboard-results.json', JSON.stringify(keyboardEvidence, null, 2) + '\n')
console.log(JSON.stringify(output, null, 2))
socket.close()
